import{_ as t,c as s,o as n,j as e,a as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易图通变卷五","description":"易图通变 - 易图通变卷五","frontmatter":{"title":"易图通变卷五","description":"易图通变 - 易图通变卷五"},"headers":[],"relativePath":"zh/classics/yitu-tongbian/006.md","filePath":"zh/classics/yitu-tongbian/006.md"}'),r={name:"zh/classics/yitu-tongbian/006.md"};function l(o,a,c,d,p,u){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易图通变卷五",tabindex:"-1"},[i("易图通变卷五 "),e("a",{class:"header-anchor",href:"#易图通变卷五","aria-label":"Permalink to “易图通变卷五”"},"​")],-1),e("p",null,"钦定四库全书",-1),e("p",null,"宋雷思齐撰",-1),e("p",null,"古圣人之王天下，创始公至理以惠启千万世者，岂易易然率己见以自擅制作哉？此有天授，断可识矣。故河之出图，伏羲因之以则而画八卦；洛之出书，大禹因之以则而叙九畴。孔子于大传叙天生神物，圣人则之，而兼及图书，而谓其兼则之也。子不语怪力乱神，岂无所见于真实，而自乐为虚诞以愚欺天下后世哉？自称庖羲氏之王天下，仰则观象于天，俯则观法于地，观鸟兽之文与地之宜，近取诸身，远取诸物，始作八卦，以通神明之德，以类万物之情，是岂先圣后圣各以私意浅识得措乎其间哉？易之广大配天地，变通配四时，阴阳之义配日月。其为书广大悉备，与乾坤相为终始而无弊，非有天授，能为是乎？此孔子有见于图书之出，特谓「则之」而已，无它说也。况图之自见于成、康，顾命陈之东序之后，无所复闻，孔子固己自悲其不出，而有己夫之叹。汉儒之始孔安国，乃由书传于河图东序之下，谓伏羲王天下，龙马负图出河，遂则其文谓之河图。于「天乃锡禹洪范九畴」之下，谓天锡禹洛书，神龟负文而出，列于背，有数从一至九，禹因而第之，以成九类，类即畴也。是二说自分载于洪范、顾命各篇本语之下，亦未之有它说也。至郑康成始引春秋纬合注大传之图、书云：河以通乾出天苞，洛以流坤吐地符。河图龙发，洛书龟感。河图有九篇，洛书有六篇，已是诡说之开端，然仍引安国之注，以为河图八卦是也，洛书九畴是也。其后王辅嗣、韩康伯于此并无所注释，惟孔颖达易疏虽全篇写郑注，亦谓辅嗣之义未知何从，是必未以郑注为然也。及其疏书之洪范，乃又引系辞云：「河出图，洛出书，圣人则之。」九类各有文字，即是书也。而云「天乃锡禹」，知此天与禹者即洛书。就引汉书五行志刘歆以为伏羲系天而王，河出图，则而画之，八卦是也。禹治洪水，锡洛书，法而陈之，洪范是也。河图、洛书相为经纬，八卦、九章相为表里。 附说：先达共为此说。龟负洛书，经无是事。中候及诸纬多说黄帝、尧、舜、禹、汤、文、武受图书之事，皆云龙负图，龟负书。纬候之书，不知谁作，通人讨核，谓伪起哀、平，虽复前汉之末始有此书，已前学者必相传此说，故孔以为九类是神龟负文而出，列于其背，有数从一至九，禹见其文，因而第之，以成九类法也。言禹第之者，以天神言语必当简要，不应曲有次第，丁宁如此，故以为语第之也。 全文 其疏顾命之「河图东序」及疏记之「河出马图」，详略虽小有殊同，指意大校若此。是则所谓河图为八卦，所谓洛书为九畴，并无改议也。",-1),e("p",null,"由汉而唐，易经行世，凡经传疏释之外，未有及于图书之文刊列经首者。迨故宋之初，陈抟图南始创意推明象数，自谓因玩索孔子三陈九卦之义，得其远旨，新有书述，特称龙图离合变通图，余二十是全用大传「天一地二至天五地十，五十有五」之数，杂以纳甲，贯穿易理。内一图谓形九宫，附一图谓形洛书者，则尽去其五生数，祇起地六至地十，自释十为用，十为成形，故洪范「陈五行之用」数语而已。及终其书，再出两图，其一形九宫者，元无改异，标为河图；其一不过尽置，列大传五十有五之数于四方及中，而自标异，谓为洛书，并无传例言说，特移二七于南，四九于西，莫可知其何所祖法而作，而标以此名，大抵因如前说洪范五行之二火四金，太玄准易因之为二南四西而然。然其流传未远，知者亦鲜。自图南五传而至刘牧长民，乃增至五十五图，名以钩隐。师友自相推许，更为唱述，各于易间有注释，曰卦德论，曰室中语，曰记师说，曰指归，曰精微，曰通神，亦总谓周易新注。每欲自神其事，及迹而究之，未见其真能有所神奇也。时则有李觏泰伯著六论以駮其非是，至谓惧其诖误学子，坏隳世教，而删其图之复重，存之者三焉：河图也，洛书也，八卦也。夫长民之多为图画，固未知其是，而泰伯亦元未识此图之三，本之则一尔。河图本列八卦，而数五十有五也。及长民辈始破洛书古说，谓非只是洪范，必别有书出于羲之上世，羲乃得而并则之，以作易也。泰伯之见，则又与之同。此愚又莫能知何为其然也。盖尝夷考大传，此章自有「法象天地，变通四时，县象日月」，而又有及于蓍龟，故因谓之「天生神物，圣人则之」者，正谓蓍也。易惟蓍是用，所谓「蓍之德员而神幽，赞于神明而生蓍」，易岂有龟事哉？因其均可以占，故牵联及龟尔。以上文谓「法象天地，变通四时」，故申之曰「天地变化，圣人效之」。上文谓「县象日月」，故申之曰「天垂象，圣人象之」。至于「天生神物」，乃申谓之如河出图，洛出书，圣人亦得以则之也。盖由河之出图，羲前既得以则而画卦，因及于洛之出书，禹后复得以则而叙畴尔，又岂害于比类而互言之哉？岂尝直欲以图书之数之义之条贯比而同之哉？岂尝直谓图书并出于一时哉？且不惟汉儒引洪范以为洛书，虽图南之初，谓形洛书者，亦不过谓十为用，十为成形，故洪范陈五行之用也者，是明指洛书为洪范矣。不知长民辈不本其初，故倍其师传，而谓洛书非出于禹之时，益使后之人迷乱而失所据依，何也？又不谓孔子之谓圣人之则之也，非特八畴分布四正四维，五行置于坎一，五事置于坤二，五纪置于巽四，五福置于离九，一以九畴之次叙陈列于河图之卦次。夫九畴谓禹次第之者，直自初一、次二、次三四，而以次用之也。今随河图十五纵横而置之，则成乱次矣，未暇一一辨诘。且以初一之五行言之，既谓五行，自当分配五方，何得以五者限萃一方，不以推行，恶得谓五行哉？以至谓「火金易位」，与河图不同，其颠倒迷缪不可训知若此。其后杨次公自著洞极经，托名于关子明，其叙本萹称：「子曰：河图之本，七前六后，八左九右，圣人观之以画八卦。是故全七之三以为离，奇以为巽；全八之三以为震，奇以为艮；全六之三以为坎，奇以为乾；全九之三以为兑，奇以为坤。正者全其位，隅者尽其画。而谓四象生八卦，此谬之尤者。乾坤相索而生六子，今为男女者，反能生父母之卦邪？况泛言二七为火，四九为金，犹可谩所未识者，今至明言离九为七，兑七为九，是河图一可变置矣，而可乎？又谓洛书之文，五处其中，九前一后，三左七右，四前左，二前右，八后左六后右，后世稽之以为三象，因而九变之以二十七象。」今案其说，惟「五处其中」一语于洛书不悖，余悉河图之数。而河图之数乃因洛书以五处中，而尽失其所以为五之理尔。书之九畴，以皇极之五处中，固无别用，是可以定去羲之时将几世几年，虽祇去禹之世，固已千数百年矣。其称书之出洛，以比羲之图之出河，于理恶乎而不可？长民故为此说，是且并孔子之大传不之信邪？考图南之为龙图，虽自谓得于孔子三陈九卦之旨而作，然其序曰：「龙图者，天散而示之，羲合而用之，孔默而形之。」且明称始图之未合，惟五十五数，则是谓大传天数二十有五，地数三十合而言之，不知何以于其末改标之以为洛书，殆其始误也，长民辈乃承误而益增其误，遂真以为洛书，而有五十五图以实其误。以至泰伯已后，悉以图南之标异之五十五数为真洛书也。不思图南标洛书之始，偶谓用十。夫洛书所叙九畴，其十数当何从而起哉？意岂谓大传之河图既可出而示世，则洛书亦可以并出示之，因假大传五十五数托为书之九畴乎？九畴所言，皆用纵比而同之谓五十五数，其用又安在哉？此不可之大者也。故尝因长民之事讨其原。图南之后，种放、许坚、李溉未及见其它有著述。若其所亲授之师，如范谔昌所著大易源流，其称「龙马负图出河，羲皇穷天人之际，重定五行生成之数，定地上八卦之体。」故老子自西周传授孔子造易之原，天一正北，地二正南，天三正东，地四正西，天五正中央，地六配子，天七配午，地八配卯，天九配酉，地十配中，寄于末，乃天地之数五十有五矣。因考其既以图之前五数置于北南东西之正及中，复以后五数配子午卯酉及中，何也？夫子午卯酉非四方之正邪？地十配中，云寄于末，夫中抑有末邪？谛详所置之数，正令图所传有四方而无四维之数者。是谔昌巳元不识图南所以标异，特因太玄准易，取于洪范一水二火三木四金五土而然，凿空无故造端老子，增立怪论，以实图南易置二七四九之位尔。然犹未尝以九畴分配九宫也。究核谔昌之取用，不过循纳甲之绪余，及五子归庚之殊向。又谓天上八卦坎离对中之外，移置乾兑坤于东，艮震巽于西，不谓五行之说多起于易后，而反引五行以为定卦之原，此又其敢于创异之大端也。是宜长民不独增以五十五图，又因谔昌坎离震兑四正之外，而以四成数同于四方，谓坎六退本卦三数，以余三数三画为乾。离七退本卦三数，以余四数四画为巽。震八数，退本卦三数，以余五数五画为艮；兑九数，退本卦三数，以余六数六画为坤。皆以数为画，标为河图，是不揣本而齐末。夫八卦各三画，以刚柔生爻，未闻本卦只用三画，而以其余画之多，反分为别卦也。所陈之数抑配偶然，且以坎离震兑为四象，则尤非也。象本在未成卦之先，故曰「四象生八卦」也。又云：洛书之九畴，本河图自然之数，虚皇极于中而以位也。至河图之有天五，乃兼地十以为十五，其五乃四分于成数之内而合于十，岂尝有五虚点而实置于图之中位哉？图之傅误正由此。五次公之假设此妄例，特以盖其所祖者，乃扬子云三方九州而二十七部私以为书耳。于斯二者，固已真易置图书矣。而朱元晦、蔡季通反祖之，信以为关子明作也，不计子明之易传精诣，岂此摹拟者比？乃循此肤臆之见，因扶其说，亦谓河图七前六后八左九右，洛书之文九前一后三左七右，四前左二前右，八后左六后右。谓大传既陈五十有五数，洪范又谓「天乃锡禹洪范九畴」，而九宫之数戴九履一，左三右七，二四为肩，六八为足，正龟背之象。刘牧意见以九为河图，十为洛书，托言出于希夷，与诸儒旧说不合。又引大传以为二者皆出于伏羲之世，其易置图书，并无明验。其朱蔡之指斥又如此。而直以「图南」始标误之洛书为河图，而以其初正指河图反以为洛书，则朱蔡实自误，而反罪长民之先误，专己自是，张其辩说，不克自反，一至于此。惟程泰之易原时能理到。至郑东卿辈寻迹依傍，一意诞谩，广增图说，皆非实指，徒使后之人失其真是，信其所不当信，疑其所不当疑，并与本来宗旨樊然扰乱，是其所非而非其所是。迹究其始，不过由「图南用十」之一语立一图之误。至于为此纷纷，始犹借河图以相因依，而为洛书之说，久则舍图取书，又久乃遂以书为图，荒然莫知河图为何物，所以有图者实为何事。执其五十五数以为图，不知其五十五数其始特以误及洛书，今反执之为图。是图既非图，其谓书以为图者，书益非其书者矣。徒自言人人殊，使学者亡羊多岐，求马唐肆，纷如聚讼，吾谁适从？不啻三百年于此。故推原致误之由，疏列群疑之妄，直以河图本数讨正之，庶几学者见之了焉，会心自断，知「图南」之谓其由三陈九卦而得者，类于谩；阴阳家袭于以一六八白取以为起例者，流于末。若乾凿度以谓太一取其数以行四正四维皆合十五者，凿于纬之拘赘，亦不尽然。然从昔儒先莫不断断然谓非人所能伪作者。今以余自本观之，直谓不必它求，特以说卦「帝出乎震」一章，环中往复参究之，以天一至地四、地六至天九求其实体，天五与地十明其虚用，则参伍以变，参天两地，错综倚数，莫不左右逢原，一皆脗合乎孔子系易之初旨，是之谓众言淆乱折诸圣，则明河之出图，通古不妄，足以见易矣。因洞悉洛之出书，九畴之外岂复有图有数之妄作者，诚古今之一大快事也。易图通变卷五。",-1)])])}const f=t(r,[["render",l]]);export{_ as __pageData,f as default};
